// AUTO-GENERATED by scripts/bundle-edge-function.mjs — do not edit by hand.
// Source of truth: supabase/functions/create-tenant-user/ (+ inlined _shared modules).
// Deploy: Supabase Dashboard → Edge Functions → create-tenant-user → paste → Deploy.

import { serve } from 'https://deno.land/std@0.208.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

// ---- create-tenant-user/index.ts -------------------------------------------------------------
// create-tenant-user — add a member to a workspace.
//
// SEC-12 (Phase 0): admins can no longer choose a member's password, and set-up / recovery
// links are never returned to the admin — only emailed to the member. Previously, adding an
// email that already had a Marbee account returned a recovery link (or let the admin set the
// password), so an admin of one workspace could take over a user of another workspace.
// Existing accounts are now simply linked and keep their own password.
//
// POST { tenant_id, email, full_name, role_id }   (any `password` field is rejected)


const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-tenant-id, x-environment',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
};

function json(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function err(message: string, status = 400) {
  return json({ error: message }, status);
}

function rpcHint(message: string): string {
  if (
    message.includes('user_has_permission_as')
    || message.includes('link_provisioned_tenant_user')
    || message.includes('invite_kind')
    || message.includes('full_name')
    || message.includes('link_active_tenant_user')
  ) {
    return `${message} — Run supabase/sql/38_provisioned_users.sql and 40_admin_password_provision.sql in the SQL editor.`;
  }
  return message;
}

function authHint(message: string, redirectTo: string): string {
  if (
    message.toLowerCase().includes('redirect')
    || message.toLowerCase().includes('url')
  ) {
    return `${message} Add this URL under Authentication → URL Configuration → Redirect URLs: ${redirectTo}`;
  }
  return message;
}

type CreateUserBody = {
  tenant_id: string;
  email: string;
  full_name: string;
  role_id: string;
  password?: unknown;
};

/** Escape LIKE/ILIKE wildcards (\, %, _) so the pattern matches the text literally. */
function escapeLike(value: string): string {
  return value.replace(/[\\%_]/g, (c) => '\\' + c);
}

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return err('Method not allowed', 405);
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
    const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY') ?? '';
    const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
    const appUrl = Deno.env.get('APP_URL') ?? Deno.env.get('SITE_URL') ?? 'http://localhost:5173';

    if (!supabaseUrl || !supabaseAnonKey || !serviceKey) {
      return err('Edge function missing Supabase env vars (URL, ANON_KEY, SERVICE_ROLE_KEY)', 500);
    }

    const authHeader = req.headers.get('authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return err('Missing authorization', 401);
    }

    const jwt = authHeader.slice(7);
    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: `Bearer ${jwt}` } },
    });

    const { data: userData, error: userError } = await userClient.auth.getUser(jwt);
    if (userError || !userData.user) {
      return err(userError?.message ?? 'Invalid session', 401);
    }

    let body: CreateUserBody;
    try {
      body = (await req.json()) as CreateUserBody;
    } catch {
      return err('Invalid JSON body');
    }

    const tenantId = body.tenant_id?.trim();
    const email = body.email?.trim().toLowerCase();
    const fullName = body.full_name?.trim();
    const roleId = body.role_id?.trim();
    if (body.password !== undefined) {
      return err('Admins can no longer set passwords. The member is emailed a link to set their own.');
    }

    if (!tenantId || !email || !fullName || !roleId) {
      return err('tenant_id, email, full_name, and role_id are required');
    }

    if (!isUuid(tenantId) || !isUuid(roleId)) {
      return err('tenant_id and role_id must be valid UUIDs');
    }

    if (!isValidEmail(email)) {
      return err('Invalid email address');
    }

    if (fullName.length < 2 || fullName.length > 120) {
      return err('Full name must be between 2 and 120 characters');
    }

    const service = createClient(supabaseUrl, serviceKey);
    const redirectTo =
      `${appUrl.replace(/\/$/, '')}/setup-password?tenant=${tenantId}&email=${encodeURIComponent(email)}`;

    const { data: canManage, error: manageErr } = await service.rpc('user_has_permission_as', {
      p_user_id: userData.user.id,
      p_tenant_id: tenantId,
      p_permission: 'access.manage',
    });
    if (manageErr) return err(rpcHint(manageErr.message), 500);

    const { data: canInvite, error: invitePermErr } = await service.rpc('user_has_permission_as', {
      p_user_id: userData.user.id,
      p_tenant_id: tenantId,
      p_permission: 'access.invite',
    });
    if (invitePermErr) return err(rpcHint(invitePermErr.message), 500);

    if (!canManage && !canInvite) {
      return err('Permission denied — your role needs access.invite or access.manage', 403);
    }

    const { data: profileRow } = await service
      .from('profiles')
      .select('id')
      // Case-insensitive but EXACT: escape LIKE wildcards so 'a_ice@x.com' can't match 'alice@x.com'.
      .ilike('email', escapeLike(email))
      .maybeSingle();

    const existingUserId = profileRow?.id as string | undefined;

    if (existingUserId) {
      const { data: activeMember } = await service
        .from('tenant_users')
        .select('status')
        .eq('tenant_id', tenantId)
        .eq('user_id', existingUserId)
        .maybeSingle();

      if (activeMember?.status === 'active') {
        return err('User is already an active member in this workspace.');
      }
    }

    let authUserId: string;
    let emailSent = false;

    if (existingUserId) {
      // Existing account: linked below, then emailed a join link (see after the link step).
      authUserId = existingUserId;
    } else {
      const { data: inviteData, error: inviteError } = await service.auth.admin.inviteUserByEmail(email, {
        data: { name: fullName, full_name: fullName },
        redirectTo,
      });
      if (inviteError || !inviteData.user) {
        console.error('create-tenant-user: invite email failed', inviteError?.message);
        return err(authHint(inviteError?.message ?? 'Could not send the invitation email', redirectTo), 502);
      }
      authUserId = inviteData.user.id;
      emailSent = true;
    }

    const { data: inviteId, error: linkError } = await service.rpc('link_provisioned_tenant_user', {
      p_tenant_id: tenantId,
      p_auth_user_id: authUserId,
      p_email: email,
      p_full_name: fullName,
      p_role_id: roleId,
      p_invited_by: userData.user.id,
      p_invite_token: null,
    });

    if (linkError) {
      if (!existingUserId) {
        await service.auth.admin.deleteUser(authUserId).catch(() => undefined);
      }
      return err(rpcHint(linkError.message), 500);
    }

    if (existingUserId) {
      // The join link (activates membership on /setup-password) goes to THEIR inbox only —
      // never back to the admin.
      const { error: sendErr } = await service.auth.resetPasswordForEmail(email, { redirectTo });
      if (sendErr) {
        console.error('create-tenant-user: join email failed', sendErr.message);
        return err(authHint(sendErr.message, redirectTo), 502);
      }
      emailSent = true;
    }

    return json({
      success: true,
      user_id: authUserId,
      invite_id: inviteId,
      email,
      full_name: fullName,
      email_sent: emailSent,
      setup_link: null,
      message: existingUserId
        ? `${email} already has a Marbee account. A link to join this workspace was emailed to them.`
        : `Invitation emailed to ${email}. They choose their own password from the link.`,
    });
  } catch (e) {
    console.error('create-tenant-user unhandled', e instanceof Error ? e.message : e);
    return err('Internal error', 500);
  }
});
